text(await tools.mcp__coding__write_file({name:"primary-publication.js",content:"const entryId = String(input?.entry_id || '1CRN').toUpperCase();
if (!/^[A-Z0-9]{4}$/.test(entryId)) throw new Error('Invalid PDB entry identifier');
async function json(url) { const r = await fetch(url); if (!r.ok) throw new Error(`HTTP ${r.status}`); return r.json(); }
const query = `query { entry(entry_id: ${JSON.stringify(entryId)}) { rcsb_id rcsb_primary_citation { id title pdbx_database_id_DOI year journal_volume page_first page_last } } }`;
const pdb = await json('https://data.rcsb.org/graphql?query=' + encodeURIComponent(query));
if (pdb.errors) throw new Error(JSON.stringify(pdb.errors));
const entry = pdb.data?.entry, citation = entry?.rcsb_primary_citation;
if (entry?.rcsb_id !== entryId || citation?.id !== 'primary' || !citation.pdbx_database_id_DOI) throw new Error('Primary citation DOI unavailable');
const doi = citation.pdbx_database_id_DOI;
const cr = await json('https://api.crossref.org/works/' + encodeURIComponent(doi));
const m = cr.message;
const normalize = s => s.toLowerCase().replace(/[^a-z0-9]/g, '');
if (cr.status !== 'ok' || m.DOI?.toLowerCase() !== doi.toLowerCase() || m.type !== 'journal-article' || !Array.isArray(m.title) || !m.title.length || !m.publisher) throw new Error('Unverified journal article metadata');
if (!m.title.some(t => normalize(t) === normalize(citation.title))) throw new Error('Primary citation title mismatch');
if (String(m.volume) !== String(citation.journal_volume) || m.page !== `${citation.page_first}-${citation.page_last}` || m.published?.['date-parts']?.[0]?.[0] !== citation.year) throw new Error('Bibliographic cross-check failed');
return {entry_id:entryId, doi:m.DOI, title:m.title, publisher:m.publisher};"}));
text(await tools.mcp__coding__write_file({name:"primary-publication.md",content:"Run primary-publication.js with input {"entry_id":"1CRN"} (or another four-character PDB entry). Uses only credential-free public reads on data.rcsb.org and api.crossref.org. RCSB's rcsb_primary_citation explicitly identifies the primary publication; Crossref must identify the matching DOI as a journal-article, not a dataset. Checks title (ignoring punctuation/case), publication year, volume and pages. Returns Crossref's exact title array and publisher. Crossref /works/{doi} was discovered from https://api.crossref.org/swagger-docs. Verified 1CRN: DOI 10.1073/pnas.81.19.6014; article published 1984, volume 81, pages 6014-6018. Throws on missing or inconsistent evidence."}));
